#!/usr/bin/env python3
# cross-platform clang-format helper: insert clang-format markers around USER CODE blocks,
# run clang-format, remove markers. Usage: python3 scripts/clang_format.py [fix|check] [all]
import sys
import re
import shutil
import subprocess
import os
from pathlib import Path
from tempfile import mkstemp
from typing import List
import difflib

# files to ignore for clang format
# this mostly includes autogenerated code
# or code imported from other libraries
EXCLUDE = [
    "dbc_to_c", # dbc_to_c autogenerated code
    "Drivers", # Drivers folder autogenerated by CubeMX
    "Middlewares", # Middlewares folder autogenerated by CubeMX
    "dbcc", # dbcc library
    "sys", # sys* files autogenerated by CubeMX
    "stm32-mw-openbl", # ST Open Bootloader library
    "eeprom_emulation", # EEPROM Emulation library
    "fff" # Fake Function Framework library
]
EXCLUDE_RE = re.compile("|".join(map(re.escape, EXCLUDE)), re.I)
FILE_RE = re.compile(r".*\.(?:c|h)$", re.I)
MODE: str = "fix"


def git_list() -> List[str]:
    cmd = ["git", "ls-files", "--cached", "--others", "--exclude-standard", "-z"]
    out = subprocess.check_output(cmd)
    if not out:
        return []
    names = out.decode("utf-8", errors="ignore").split("\0")
    return [n for n in names if n and FILE_RE.match(n) and not EXCLUDE_RE.search(n)]


def _clang_format_version_ok(cf_path: str) -> bool:
    try:
        out = subprocess.check_output([cf_path, "--version"], text=True, stderr=subprocess.STDOUT)
    except Exception:
        return False
    # Expected: "clang-format version 21.1.8"
    m = re.search(r"clang-format version (\d+)", out)
    if not m:
        return False
    return int(m.group(1)) >= 21


def find_clang_format() -> str:
    cf = shutil.which("clang-format") or shutil.which("clang-format.exe")
    if not cf:
        print(
            "clang-format not found in PATH; install it or add it to PATH.",
            file=sys.stderr,
        )
        sys.exit(1)
    if not _clang_format_version_ok(cf):
        print(
            "clang-format version 21 or higher is required.",
            file=sys.stderr,
        )
        sys.exit(1)
    return cf


def backup_path(p: Path) -> Path:
    return p.with_suffix(p.suffix + ".bak")


def read_text(p: Path) -> str:
    return p.read_text(encoding="utf-8", errors="surrogateescape")


def write_text(p: Path, data: str) -> None:
    # keep universal newlines handling consistent
    p.write_text(data, encoding="utf-8", errors="surrogateescape")


def process_file(p: Path) -> None:
    orig = read_text(p)

    # Insert clang-format-on after USER CODE BEGIN, preserving existing blank lines:
    def repl_begin(m: re.Match) -> str:
        indent = m.group(1)
        comment = m.group(2)
        following = m.group(3) or ""
        # keep existing blank lines but ensure at least one newline and place marker on its own line
        rest = following[1:] if following else ""
        return f"{indent}{comment}\n{indent}/* clang-format on */\n{rest}"

    s = re.sub(
        r'(?ms)(^[ \t]*)(/\* USER CODE BEGIN .*?\*/)(\r?\n*)',
        repl_begin,
        orig,
    )

    # Insert clang-format-off before USER CODE END, preserving existing blank lines:
    def repl_end(m: re.Match) -> str:
        indent = m.group(1)
        end_comment = m.group(2)
        following = m.group(3) or ""
        rest = following[1:] if following else ""
        return f"{indent}/* clang-format off */\n{indent}{end_comment}\n{rest}"

    s = re.sub(
        r'(?ms)(^[ \t]*)(/\* USER CODE END .*?\*/)(\r?\n*)',
        repl_end,
        s,
    )

    write_text(p, s)


def remove_markers_and_write(p: Path) -> None:
    s = read_text(p)
    # remove marker lines (keep surrounding/newline context intact)
    s = re.sub(r'(?m)^[ \t]*\/\* clang-format on \*\/\r?\n', '', s)
    s = re.sub(r'(?m)^[ \t]*\/\* clang-format off \*\/\r?\n', '', s)
    write_text(p, s)


def detect_runner() -> str:
    env = os.environ
    if env.get("GITHUB_ACTIONS") == "true":
        return "github_actions"
    if env.get("ACT") or env.get("ACT_RUNNER"):
        return "act"
    if env.get("CI") == "true":
        return "ci"
    if env.get("PRE_COMMIT_HOME") is not None:
        return "pre-commit"
    return "local"


# use it to choose behavior
runner = detect_runner()
if runner == "github_actions":
    MODE = "check"


def main() -> None:
    # first determinte if clang format is installed
    cf = find_clang_format()
    
    files = git_list()
    if not files:
        return
    paths = [Path(f) for f in files]
    # backups
    for p in paths:
        bp = backup_path(p)
        bp.write_bytes(p.read_bytes())

    # insert markers
    for p in paths:
        process_file(p)

    # run clang-format
    subprocess.run([cf, "-i", *[str(p) for p in paths]], check=True)

    # remove markers
    for p in paths:
        remove_markers_and_write(p)

    if MODE == "check":
        changed = False
        for p in paths:
            bp = backup_path(p)
            new = p.read_bytes()
            if bp.exists():
                old = bp.read_bytes()
                # restore original file
                p.write_bytes(old)
                try:
                    bp.unlink()
                except FileNotFoundError:
                    pass
            else:
                old = new

            if new != old:
                # show a unified diff to diagnose byte differences (use surrogateescape to preserve bytes)
                old_s = old.decode("utf-8", errors="surrogateescape").splitlines(keepends=True)
                new_s = new.decode("utf-8", errors="surrogateescape").splitlines(keepends=True)
                diff = difflib.unified_diff(old_s, new_s, fromfile=f"old/{p}", tofile=f"new/{p}")
                print("Formatting required:", p)
                for line in diff:
                    # print raw repr for non-printable differences at start/end
                    print(line, end="")
                changed = True
        sys.exit(1 if changed else 0)
    else:
        # fix: remove backups and add files to git
        for p in paths:
            bp = backup_path(p)
            if bp.exists():
                bp.unlink()
        if paths:
            subprocess.run(["git", "add", *[str(p) for p in paths]], check=False)


if __name__ == "__main__":
    main()